def submit(flag: str) -> bool:
    """ Submit the flag """
    import subprocess
    try:
        print(f"[*] Submitting flag: {flag}")
        print(subprocess.check_output(["dojo", "submit", flag], text=True))
        return True
    except subprocess.CalledProcessError as e:
        print(f"[!] Submitting fail: returncode={e.returncode}")
        print((e.output or ''), (e.stderr or ''))
        return False


def find_challenge(search_path="/challenge"):
    from pathlib import Path
    import os
    import stat

    exts = [".py", ".c", ".ko", ".so"]
    xs = [
        str(f.absolute())
        for f in Path(search_path).iterdir()
        if f.is_file()
        and not f.name.startswith(".")
        and not any(f.name.endswith(ext) for ext in exts)
        and os.access(f, os.X_OK)
        and (f.stat().st_mode & stat.S_ISUID)
    ]
    if not xs:
        raise FileNotFoundError(f"No executable found in {search_path}")
    if len(xs) > 1:
        raise FileNotFoundError(f"Multiple executables found in {search_path}")
    return xs[0]

def aslr(addr: int, bits: int = 12):
    """
    Generate partial-address candidates while preserving the lowest `bits`
    bits of `addr`.

    The result width is rounded up to the nearest whole byte. Any bits between
    `bits` and that byte boundary are enumerated.

    Common `bits` values include:
    - 12 for 4 KiB pages, like userspace virtual memory
    - 21 for 2 MiB pages, like kernel kASLR address
    """
    assert addr > 0, "addr must be positive"
    assert bits > 0, "bits must be positive"

    result_bits = ((bits + 7) // 8) * 8
    variable_bits = result_bits - bits
    fixed_part = addr & ((1 << bits) - 1)

    for value in range(1 << variable_bits):
        yield (value << bits) | fixed_part


def patch(data, patches):
    """Apply {offset: bytes} patches to data and return new bytes."""
    items = sorted(patches.items())

    prev_end = 0
    for offset, value in items:
        if offset < prev_end:
            raise ValueError(f"overlapping patch at offset {offset:#x}")
        prev_end = offset + len(value)

    data = bytearray(data)
    for offset, value in items:
        data[offset:offset + len(value)] = value
    return bytes(data)


def setup_pwn_context():
    """ Setup pwntools context if it is imported before dojotool """
    import sys

    pwn = sys.modules.get("pwn")
    if pwn is not None:
        pwn.context.update(arch="amd64", os="linux", terminal=["tmux", "new-window"])

# Global Initialization
setup_pwn_context()
